package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

type PartRec struct {
	LbPart   string // PIC X(8) @0 len=8
	LbRegion string // PIC X(3) @8 len=3
	LbSerial int64  // PIC 9(4) @11 len=4
}

var WsEofFlag string // PIC X len=1 = "N"
var WsLabel string   // PIC X(20) len=20 = SPACES
var WsACount int64   // PIC 99 len=2 = 0
var WsTotalA int64   // PIC 999 len=3 = 0
var WsCount int64    // PIC 999 len=3 = 0

var PartRecVar PartRec

var inputRecords []string
var inputIndex int

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func formatInt(v int64, digits int) string {
	s := fmt.Sprintf("%d", v)
	// keep low-order digits if overflow
	if len(s) > digits {
		s = s[len(s)-digits:]
	} else if len(s) < digits {
		s = strings.Repeat("0", digits-len(s)) + s
	}
	return s
}

func padRight(s string, n int) string {
	if len(s) > n {
		return s[:n]
	}
	if len(s) < n {
		return s + strings.Repeat(" ", n-len(s))
	}
	return s
}

func delimitedBySpace(s string) string {
	idx := strings.Index(s, " ")
	if idx >= 0 {
		return s[:idx]
	}
	return s
}

func MainPara() {
	// OPEN INPUT PART-FILE
	f, err := os.Open("input.dat")
	if err != nil {
		// if file not exists, treat as empty (COBOL would error, but for safety)
		inputRecords = []string{}
	} else {
		scanner := bufio.NewScanner(f)
		for scanner.Scan() {
			line := scanner.Text()
			// Remove possible carriage return already stripped, but handle \r
			line = strings.TrimSuffix(line, "\r")
			if len(line) < 15 {
				line = line + strings.Repeat(" ", 15-len(line))
			} else if len(line) > 15 {
				line = line[:15]
			}
			inputRecords = append(inputRecords, line)
		}
		f.Close()
	}
	inputIndex = 0
	WsEofFlag = "N"
	WsLabel = strings.Repeat(" ", 20)
	WsACount = 0
	WsTotalA = 0
	WsCount = 0

	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	// CLOSE PART-FILE
	SummaryPara()
}

func ReadPara() {
	if inputIndex >= len(inputRecords) {
		WsEofFlag = "Y"
		return
	}
	rec := inputRecords[inputIndex]
	inputIndex++
	// parse 15 bytes
	PartRecVar.LbPart = rec[0:8]
	PartRecVar.LbRegion = rec[8:11]
	serialStr := rec[11:15]
	// serial is digits; parse
	// If not numeric, treat as 0
	var v int64 = 0
	for _, c := range serialStr {
		if c >= '0' && c <= '9' {
			v = v*10 + int64(c-'0')
		}
	}
	PartRecVar.LbSerial = v
}

func ProcessPara() {
	WsLabel = strings.Repeat(" ", 20)
	WsACount = 0

	// INSPECT LB-PART TALLYING FOR ALL "A"
	cnt := strings.Count(PartRecVar.LbPart, "A")
	WsACount = int64(cnt)

	// STRING ... INTO WS-LABEL
	partRegion := delimitedBySpace(PartRecVar.LbRegion)
	partPart := delimitedBySpace(PartRecVar.LbPart)
	serialFormatted := formatInt(PartRecVar.LbSerial, 4)

	parts := []string{partRegion, "-", partPart, "-", serialFormatted}
	combined := strings.Join(parts, "")
	// STRING into WS-LABEL: overlay from start, truncate if longer than 20
	b := []byte(strings.Repeat(" ", 20))
	for i := 0; i < len(combined) && i < 20; i++ {
		b[i] = combined[i]
	}
	WsLabel = string(b)

	// INSPECT WS-LABEL REPLACING ALL "0" BY "O"
	WsLabel = strings.ReplaceAll(WsLabel, "0", "O")

	// ADDs
	WsTotalA += WsACount
	WsCount += 1

	// DISPLAY WS-LABEL " A=" WS-A-COUNT
	// WS-LABEL is X(20) exactly, WS-A-COUNT is 99 zero-padded 2
	fmt.Printf("%s A=%s\n", WsLabel, formatInt(WsACount, 2))

	ReadPara()
}

func SummaryPara() {
	fmt.Printf("LABELS: %s A-TOTAL: %s\n", formatInt(WsCount, 3), formatInt(WsTotalA, 3))
}

func main() {
	MainPara()
}
